def compute(vars):
    outstanding = vars["v1"]
    original_principal = vars["v2"]

    if original_principal == 0:
        return None

    percentage_outstanding = (outstanding / original_principal) * 100

    return {
        "value": percentage_outstanding,
        "trace": {
            "outstanding": outstanding,
            "original_principal": original_principal,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
